if (a - 1) // m == (b - 1) // m:
	print(1)
elif (a - 1) % m == 0 and b % m == 0:
	print(1)
elif (a - 1) % m == 0 and b == n or m == 1:
	print(1)
elif (a - 1) % m == 0 or b % m == 0 or b == n:
	print(2)
elif abs((a - 1) // m - (b - 1) // m) == 1 or m == 2:
	print(2)
elif (a - 1) % m == b % m:
	print(2)
